import sys as _sys, os as _os, types as _types, base64 as _b64, zlib as _zlib
import json as _json
import importlib.machinery as _mach
import importlib.util as _iutil

_BUNDLE_DIR = _os.path.dirname(_os.path.abspath(__file__))
if _BUNDLE_DIR not in _sys.path:
    _sys.path.insert(0, _BUNDLE_DIR)

_RAW = _json.loads(_zlib.decompress(_b64.b64decode("")).decode("utf-8"))
_MODULE_SRCS = _RAW["modules"]
_MAIN_SRC = _RAW["main"]

# 点分包名 -> 仓库内相对路径（含 __init__ 标记）
_NAME_TO_REL = {}
for _rel in _MODULE_SRCS:
    _n = _rel[:-3].replace("/", ".")
    if _n.endswith(".__init__"):
        _n = _n[: -len(".__init__")]
    _NAME_TO_REL[_n] = _rel


class _BundleLoader:
    """按需 exec 内嵌源码；由标准导入机制驱动，循环导入/相对导入语义与磁盘包一致。"""

    def create_module(self, spec):
        return None  # 使用默认 module 创建

    def exec_module(self, module):
        _name = module.__name__
        _rel = _NAME_TO_REL[_name]
        module.__file__ = _os.path.join(_BUNDLE_DIR, *_rel.split("/"))
        if _rel.endswith("/__init__.py"):
            module.__path__ = [_os.path.dirname(module.__file__)]
        exec(compile(_MODULE_SRCS[_rel], module.__file__, "exec"), module.__dict__)


_LOADER = _BundleLoader()


class _BundleFinder:
    def find_spec(self, fullname, path=None, target=None):
        if fullname == "modules":
            # 命名空间根包（modules/ 下无 __init__.py，与文件夹版一致）
            _root = _os.path.join(_BUNDLE_DIR, "modules")
            spec = _mach.ModuleSpec(fullname, loader=None, is_package=True)
            spec.submodule_search_locations = [_root]
